const s = $('Settings Loader').first().json;
const trigger = $('Twilio Call Status').first().json;
const body = (trigger.body && typeof trigger.body === 'object') ? trigger.body : trigger;
const callStatus = (body.CallStatus || '').toLowerCase();
const missedStatuses = s.missed_call_statuses;
if (!missedStatuses.includes(callStatus)) return [];
const callerPhone = body.From || body.Caller || '';
if (!callerPhone) return [];
return [{ json: {
  source: 'Phone',
  phone: callerPhone,
  callStatus: body.CallStatus || '',
  callSid: body.CallSid || '',
  calledNumber: body.To || body.Called || '',
  status: 'New'
}}];

const s = $('Settings Loader').first().json;
const CONFIG = {
  COMPANY_NAME: s.business_name,
  INTAKE_FORM_URL: s.intake_form_url
};

const render = (tpl, vars) => tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => (vars[k] !== undefined && vars[k] !== null) ? vars[k] : '');

const lead = $json;

const smsMessage = render(s.sms_template_missed_call, { businessName: CONFIG.COMPANY_NAME, intakeFormUrl: CONFIG.INTAKE_FORM_URL });

return [{
  json: {
    ...lead,
    message: smsMessage
  }
}];

const lead = $('Build SMS Request').first().json;

return [{
  json: {
    source: 'Phone',
    phone: lead.phone,
    status: 'New',
    logChannel: 'Phone',
    logDirection: 'Inbound',
    logHandler: 'System',
    logSummary: 'Missed call — auto-SMS sent',
    logNotes:
      'CallStatus: ' + (lead.callStatus || '') +
      ' | CallSid: ' + (lead.callSid || '') +
      ' | SMS sent: ' + (lead.message || '')
  }
}];

const lead = $('Validate Missed Call').first().json;
const logs = $input.all().map(i => i.json);
const isDuplicate = lead.callSid ? logs.some(l => String(l['Notes'] || '').includes('CallSid: ' + lead.callSid)) : false;
return [{ json: { ...lead, isDuplicate } }];
